'use strict';
// Demo: el personaje de la guarida dibujado con la hoja de sprites del usuario (img/pj-hoja.webp, incrustada abajo para que funcione por file://):
// arriba-izquierda de frente, arriba-derecha de perfil (mira a la izquierda) y abajo-derecha de espalda.
// Solo se carga desde demo-pj.html; usa la ranura 4 (invisible) y no toca las partidas reales.
const DEMO_H = 46;   // alto del sprite en píxeles de mundo
let DEMO_V = null;   // vistas: {front, side, back}, cada una con 3 fotogramas [pie, paso A, paso B]
{
  const im = new Image();
  im.onload = () => {
    const c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
    const g = c.getContext('2d', {willReadFrequently:true}); g.drawImage(im, 0, 0);
    const d = g.getImageData(0, 0, c.width, c.height), W = c.width, H = c.height, px = d.data;
    const white = p => px[p*4 + 3] > 20 && Math.min(px[p*4], px[p*4 + 1], px[p*4 + 2]) > 222;
    const clear = p => { px[p*4 + 3] = 0; };
    const gone = p => px[p*4 + 3] < 20;
    // 1) fondo conectado a los bordes
    const seen = new Uint8Array(W*H), st = [];
    for(let x = 0; x < W; x++) st.push(x, x + (H - 1)*W);
    for(let y = 0; y < H; y++) st.push(y*W, y*W + W - 1);
    while(st.length){ const p = st.pop(); if(seen[p] || !(gone(p) || white(p))) continue; seen[p] = 1; clear(p); const x = p % W; if(x > 0) st.push(p - 1); if(x < W - 1) st.push(p + 1); if(p >= W) st.push(p - W); if(p < W*(H - 1)) st.push(p + W); }
    // 2) bolsas de blanco encerradas (entre brazos y cuerpo): se borran las grandes; los brillos pequeños (ojos) se quedan
    const mark = new Uint8Array(W*H);
    for(let s = 0; s < W*H; s++){
      if(mark[s] || !white(s)) continue;
      const comp = [s]; mark[s] = 1; for(let i = 0; i < comp.length; i++){ const p = comp[i], x = p % W; for(const q of [x > 0 ? p - 1 : -1, x < W - 1 ? p + 1 : -1, p - W, p + W]) if(q >= 0 && q < W*H && !mark[q] && white(q)){ mark[q] = 1; comp.push(q); } }
      if(comp.length > 160) for(const p of comp) clear(p);
    }
    // 3) halo claro pegado al vacío
    for(let pass = 0; pass < 3; pass++){
      const kill = [];
      for(let y = 1; y < H - 1; y++) for(let x = 1; x < W - 1; x++){ const p = y*W + x; if(gone(p)) continue; if((gone(p - 1) || gone(p + 1) || gone(p - W) || gone(p + W)) && Math.min(px[p*4], px[p*4 + 1], px[p*4 + 2]) > 200) kill.push(p); }
      for(const p of kill) clear(p);
    }
    // recorte de cada vista (cuadrantes de la hoja)
    const mx = W >> 1, my = H >> 1;
    const box = (qx0, qx1, qy0, qy1) => { let x0 = W, x1 = 0, y0 = H, y1 = 0; for(let y = qy0; y < qy1; y++) for(let x = qx0; x < qx1; x++) if(!gone(y*W + x)){ if(x < x0) x0 = x; if(x > x1) x1 = x; if(y < y0) y0 = y; if(y > y1) y1 = y; } return {x0, x1, y0, y1, w:x1 - x0 + 1, h:y1 - y0 + 1}; };
    const build = (bx, kind) => {
      const {x0, y0, w:sw, h:sh} = bx, cx = x0 + sw/2, fy = y => (y - y0)/sh, fx = x => (x - x0)/sw;
      const part = pred => { const o = document.createElement('canvas'); o.width = W; o.height = H; const og = o.getContext('2d'), od = og.createImageData(W, H);
        for(let y = bx.y0; y <= bx.y1; y++) for(let x = bx.x0; x <= bx.x1; x++){ const p = y*W + x; if(gone(p) || !pred(x, y)) continue; od.data.set(px.subarray(p*4, p*4 + 4), p*4); } og.putImageData(od, 0, 0); return o; };
      const legL = part((x, y) => fy(y) >= .74 && x < cx), legR = part((x, y) => fy(y) >= .74 && x >= cx);
      const side = kind === 'side';
      const armL = part((x, y) => fy(y) > .44 && fy(y) < .74 && (side ? fx(x) > .2 && fx(x) < .6 : fx(x) < .26));
      const armR = side ? null : part((x, y) => fy(y) > .44 && fy(y) < .74 && fx(x) > .76);
      const body = part((x, y) => fy(y) < .74);
      const k = DEMO_H/sh, L = Math.round(sh*.05), A = Math.round(sh*.03);
      const compose = (ll, lr, al, ar) => {   // cada desplazamiento es [dx, dy]
        const o = document.createElement('canvas'); o.width = W; o.height = H; const og = o.getContext('2d');
        og.drawImage(legL, ll[0], ll[1]); og.drawImage(legR, lr[0], lr[1]); og.drawImage(body, 0, 0); og.drawImage(armL, al[0], al[1]); if(armR) og.drawImage(armR, ar[0], ar[1]); return o; };
      const z = [0, 0];
      const frames = side
        ? [compose(z, z, z, z), compose([-L, -L*.4], [L, 0], [A*2, 0], z), compose([L, 0], [-L, -L*.4], [-A*2, 0], z)]
        : [compose(z, z, z, z), compose([0, -L], z, [0, A], [0, -A]), compose(z, [0, -L], [0, -A], [0, A])];
      return frames.map(f => {
        const ow = Math.round(sw*k) + 4, oh = Math.ceil((sh + L)*k) + 4, o = document.createElement('canvas'); o.width = ow; o.height = oh;
        const og = o.getContext('2d', {willReadFrequently:true}); og.imageSmoothingEnabled = true; og.imageSmoothingQuality = 'high';
        og.drawImage(f, x0 - 2/k, y0 - L - 2/k, sw + 4/k, sh + L + 4/k, 0, 0, ow, Math.round((sh + L)*k + 4));
        const id = og.getImageData(0, 0, ow, oh), a = id.data;
        for(let i = 3; i < a.length; i += 4) a[i] = a[i] > 120 ? 255 : 0;           // bordes duros (pixel art)
        const op = new Uint8Array(ow*oh); for(let i = 0; i < ow*oh; i++) op[i] = a[i*4 + 3] ? 1 : 0;
        for(let y = 0; y < oh; y++) for(let x = 0; x < ow; x++){ const i = y*ow + x; if(op[i]) continue;   // contorno negro de 1 píxel
          if((x > 0 && op[i - 1]) || (x < ow - 1 && op[i + 1]) || (y > 0 && op[i - ow]) || (y < oh - 1 && op[i + ow])){ a[i*4] = 14; a[i*4 + 1] = 10; a[i*4 + 2] = 12; a[i*4 + 3] = 255; } }
        og.putImageData(id, 0, 0); return o;
      });
    };
    DEMO_V = {front:build(box(0, mx, 0, my), 'front'), side:build(box(mx, W, 0, my), 'side'), back:build(box(mx, W, my, H), 'back')};
  };
  im.src = 'data:image/webp;base64,';
}
loadGame = (_l => slot => { const s = _l(slot); s.introDone = true; s.tut = 99; s.quest = 'done'; s.level = Math.max(s.level, 5); s.name = s.name || 'Demo'; return s; })(loadGame);
drawHero = function(){
  if(P.dead) return;
  b.imageSmoothingEnabled = false;
  const x = Math.round(P.x), y = Math.round(P.y), cs = Math.cos(P.face), sn = Math.sin(P.face);
  const s = P.moving ? Math.sin(P.walk*1.15) : 0;
  const bob = P.moving ? -Math.round(Math.abs(s)*2) : (Math.sin(G.t*2.5) > .6 ? -1 : 0);
  const jz = Math.round(P.jumpZ || 0);
  pshadow(x, y, 12 - (jz >> 2), 4 - (jz >> 4));
  if(!DEMO_V) return;
  const view = Math.abs(cs) > Math.abs(sn)*.9 ? 'side' : sn > 0 ? 'front' : 'back';
  const fr = DEMO_V[view][P.moving && !jz ? (s > .35 ? 1 : s < -.35 ? 2 : 0) : 0];
  const sq = P.moving ? 1 - Math.abs(s)*.04 : 1 + (bob ? .02 : 0);   // aplasta un poco en cada paso / respira
  b.save(); b.translate(x, y - jz + bob); b.rotate(view === 'side' ? s*.03 : s*.06); b.scale(view === 'side' && cs > 0 ? -1 : 1, sq);
  b.drawImage(fr, -(fr.width >> 1), -fr.height + 3);
  b.restore();
};
document.addEventListener('DOMContentLoaded', () => {
  const t = setInterval(() => {
    if(typeof startGame !== 'function' || performance.now() < 1200) return;
    clearInterval(t);
    startGame(4, true);
  }, 100);
});
